<?php
namespace Proma\Plugins\SignConnect\Controllers;
use Proma\Plugins\SignConnect\Services\NotificationEventCatalog;
use Proma\Plugins\SignConnect\Services\SettingsService;
final class NotificationRuleController extends \Controller
{
    public function save(){$this->onlyPost();$catalog=new NotificationEventCatalog();$settings=(new SettingsService())->all(false);$saved=0;\Model::begin();try{foreach(($_POST['events']??[])as$event=>$row){$event=preg_replace('/[^a-z0-9._-]/','',(string)$event);$definition=$catalog->find($event);if(!$definition||!is_array($row))continue;$channels=[];foreach(['in_app','ippanel','smsir','bale','telegram']as$c){$mode=in_array(($row['channels'][$c]??'disabled'),['disabled','primary','fallback','simultaneous','linked_only'],true)?$row['channels'][$c]:'disabled';if($mode!=='disabled'&&($settings['provider_'.$c.'_enabled']??'0')!=='1')throw new \InvalidArgumentException('کانال «'.$c.'» برای رویداد '.$definition['title_fa'].' فعال نیست.');$channels[$c]=$mode;}$enabled=!empty($row['enabled'])?1:0;if(!empty($definition['mandatory']))$enabled=1;if($enabled&&!array_filter($channels,fn($v)=>$v!=='disabled'))throw new \InvalidArgumentException('برای رویداد '.$definition['title_fa'].' حداقل یک کانال انتخاب کنید.');\Model::execute("INSERT INTO proma_connect_notification_rules (event_key,is_enabled,sensitivity,recipients_json,channels_json,provider_priority_json,template_key,delay_seconds,max_sends,dedupe_seconds,policy_json,updated_by,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?, ?,NOW()) ON DUPLICATE KEY UPDATE is_enabled=VALUES(is_enabled),sensitivity=VALUES(sensitivity),channels_json=VALUES(channels_json),updated_by=VALUES(updated_by),updated_at=NOW()",[$event,$enabled,in_array(($row['sensitivity']??''),['service','financial','confidential','security','legal'],true)?$row['sensitivity']:$definition['sensitivity'],$definition['allowed_recipients_json'],json_encode($channels),'[]',$row['template_key']??null,0,1,300,'{}',\Auth::id()]);$saved++;}\Model::execute("INSERT INTO proma_connect_settings_audit (section_key,action_key,actor_id,after_json,request_id,created_at) VALUES ('notifications','rules_saved',?,?,?,NOW())",[\Auth::id(),json_encode(['count'=>$saved]),\ErrorHandler::requestId()]);\Model::commit();\set_flash('success','قوانین اعلان ذخیره شد.');}catch(\InvalidArgumentException$e){\Model::rollBack();\set_flash('error',$e->getMessage());}catch(\Throwable$e){\Model::rollBack();\set_flash('error','ذخیره قوانین انجام نشد. شناسه پیگیری: '.\ErrorHandler::requestId());}\redirect('plugin/sign-connect/settings/notifications');}
}
